/**
 * PLANNER OUTPUT NORMALIZER (v10.13 - Placeholder Ghost Text Purged)
 * Responsibility: Extracting JSON from LLM while preserving the active loop state.
 * Execution Mode: Run once for each item.
 */

// 1. STATE RECOVERY (Targeted to local Subflow Trigger node)
const incomingContext = $("When Executed by Another Workflow").item.json;

const orderDetails = incomingContext.order_details;
const currentRound = incomingContext.audit_round || 1; 
const isReflection = incomingContext.is_reflection || false;
const archetype = incomingContext.problem_archetype;
const drivers = incomingContext.drivers || [];
const sopContext = incomingContext.sop_context;
const mappedDomain = incomingContext.mapped_domain || "General";

// ─── FIXED: Force an absolute empty string default instead of the text placeholder ───
const rejectionReasonsLog = incomingContext.rejection_reasons_log || "";

let rawText = $json.text || "";

// 2. EXTRACT JSON BLOCK
const startIdx = rawText.indexOf('{');
const endIdx = rawText.lastIndexOf('}');

if (startIdx === -1 || endIdx === -1) {
    return { 
        error: "No JSON object found", 
        raw_text: rawText,
        order_details: orderDetails,
        audit_round: currentRound,
        is_reflection: isReflection,
        problem_archetype: archetype,
        mapped_domain: mappedDomain,
        drivers: drivers,
        sop_context: sopContext,
        rejection_reasons_log: rejectionReasonsLog
    };
}

let cleanJson = rawText.substring(startIdx, endIdx + 1).trim();

// 3. PARSING ATTEMPT WITH FALLBACKS
let parsed;
try {
    parsed = JSON.parse(cleanJson);
} catch (e) {
    try {
        parsed = JSON.parse(cleanJson.replace(/,\s*}/g, "}"));
    } catch (err) {
        return { 
            error: "Structural Failure", 
            raw_text: cleanJson,
            order_details: orderDetails,
            audit_round: currentRound,
            is_reflection: isReflection,
            problem_archetype: archetype,
            mapped_domain: mappedDomain,
            drivers: drivers,
            sop_context: sopContext,
            rejection_reasons_log: rejectionReasonsLog
        };
    }
}

// 4. DYNAMIC DATA MAPPING
return {
    driver: parsed.identified_driver || archetype,
    symbolic_mapping: parsed.symbolic_mapping || "Unmapped",
    rationale: parsed.logic_rationale,
    steps: parsed.proposed_steps || [],
    communication: parsed.customer_communication,
    escalation_flag: parsed.escalation_flag || false,

    // --- Stateful Suitcase (Carried Forward Safely) ---
    order_details: orderDetails,
    audit_round: currentRound,
    is_reflection: isReflection,
    problem_archetype: archetype,
    mapped_domain: mappedDomain, 
    drivers: drivers,

    // ─── FIXED TYPO: Restored correct object property mapping key ───
    sop_context: sopContext,

    // Forward historical audit logs seamlessly up the execution path
    rejection_reasons_log: rejectionReasonsLog
};
